def comparer(xs_app, ys_app, xs_test, ys_test):
    mx = sum(xs_app) / len(xs_app)
    my = sum(ys_app) / len(ys_app)
    a = sum((x - mx) * (y - my) for x, y in zip(xs_app, ys_app)) / sum((x - mx) ** 2 for x in xs_app)
    b = my - a * mx
    ref = erreur_moyenne([my] * len(ys_test), ys_test)
    dro = erreur_moyenne([a * x + b for x in xs_test], ys_test)
    return {"reference": ref, "droite": dro, "meilleur": "droite" if dro <= ref else "reference"}

