import re

COURRIEL = r"[\w.+-]+@[\w-]+(\.[\w-]+)+"
TELEPHONE = r"(\+228\s?)?\d{2}(\s?\d{2}){3}"


def masquer(texte):
    texte = re.sub(COURRIEL, "[courriel]", texte)
    return re.sub(TELEPHONE, "[téléphone]", texte)


def rapport(texte):
    courriels = len(list(re.finditer(COURRIEL, texte)))
    sans_courriels = re.sub(COURRIEL, "", texte)
    telephones = len(list(re.finditer(TELEPHONE, sans_courriels)))
    pret = re.search(r"mot de passe", texte, re.IGNORECASE) is None
    return {"courriels": courriels, "telephones": telephones, "texte": masquer(texte), "pret": pret}

